108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        rejectMissingOrBlankFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        owner.setAddress(normalizeAddress(owner.getAddress()));
125	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
126	        owner.setEmail(normalizeEmail(owner.getEmail()));
127	        if (owner.getRegistrationDate() == null) {
128	            owner.setRegistrationDate(LocalDate.now());
129	        }
130	        rejectDuplicateTelephone(owner.getTelephone());
131	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
132	            assignHousehold(owner);
133	        } else {
134	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
135	        }
136	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
137	        this.clinicService.saveOwner(owner);
138	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
139	        headers.setLocation(UriComponentsBuilder.newInstance()
140	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
141	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
147	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
148	        if (currentOwner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        currentOwner.setAddress(ownerFieldsDto.getAddress());
152	        currentOwner.setCity(ownerFieldsDto.getCity());
153	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
154	        currentOwner.setLastName(ownerFieldsDto.getLastName());
155	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
156	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
157	        this.clinicService.saveOwner(currentOwner);
158	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Transactional
163	    @Override
164	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
165	        Owner owner = this.clinicService.findOwnerById(ownerId);
166	        if (owner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        this.clinicService.deleteOwner(owner);
170	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
