232	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    /**
239	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
240	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
241	     *
242	     * @param fields the submitted owner fields
243	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
244	     *                                        {@code null} or blank, or if address is blank after
245	     *                                        normalization
246	     */
247	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
248	        List<String> missing = new ArrayList<>();
249	        if (isBlank(fields.getFirstName())) {
250	            missing.add("firstName");
251	        }
252	        if (isBlank(fields.getLastName())) {
253	            missing.add("lastName");
254	        }
255	        if (isBlank(normalizeAddress(fields.getAddress()))) {
256	            missing.add("address");
257	        }
258	        if (isBlank(fields.getCity())) {
259	            missing.add("city");
260	        }
261	        if (isBlank(fields.getTelephone())) {
262	            missing.add("telephone");
263	        }
264	        if (!missing.isEmpty()) {
265	            throw new RequiredFieldsMissingException(missing);
266	        }
267	    }
268	
269	    private boolean isBlank(String value) {
270	        return value == null || value.isBlank();
271	    }
272	
273	    /**
274	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
275	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
276	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
277	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
278	     *
279	     * @param telephone the raw telephone value from the request
280	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
281	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
282	     */
283	    private String normalizeTelephone(String telephone) {
284	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
285	        String digits;
286	        if (cleaned.startsWith("+")) {
287	            digits = cleaned.substring(1);
288	        } else {
289	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
290	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
291	            digits = "61" + national;
292	        }
293	        if (!digits.matches("[0-9]{8,15}")) {
294	            throw new InvalidTelephoneException(cleaned);
295	        }
296	        return "+" + digits;
297	    }
298	
299	    /**
300	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
301	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
302	     * lower-cased.
303	     *
304	     * @param email the raw email value from the request, or {@code null} if omitted
305	     * @return the lower-cased email, or {@code null} if none was supplied
306	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
307	     */
308	    private String normalizeEmail(String email) {
309	        if (email == null) {
310	            return null;
311	        }
312	        String trimmed = email.strip();
313	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
314	            throw new InvalidEmailException(email);
315	        }
316	        return trimmed.toLowerCase(Locale.ROOT);
317	    }
318	
319	    /**
320	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
321	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
322	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
323	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
324	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
325	     *
326	     * @param address the raw address value from the request (may be {@code null})
327	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
328	     */
329	    private String normalizeAddress(String address) {
330	        if (address == null) {
331	            return "";
332	        }
333	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
334	        if (collapsed.isEmpty()) {
335	            return "";
336	        }
337	        String[] tokens = collapsed.split(" ");
338	        StringBuilder sb = new StringBuilder(collapsed.length());
339	        for (int i = 0; i < tokens.length; i++) {
340	            if (i > 0) {
341	                sb.append(' ');
342	            }
343	            sb.append(expandAddressAbbreviation(tokens[i]));
344	        }
345	        return sb.toString();
346	    }
347	
348	    /**
349	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
350	     * returns the token unchanged when it is not a recognised abbreviation.
351	     *
352	     * @param token an upper-cased whole-word address token
353	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
354	     */
355	    private String expandAddressAbbreviation(String token) {
356	        return switch (token) {
357	            case "ST" -> "STREET";
358	            case "RD" -> "ROAD";
359	            case "AVE" -> "AVENUE";
360	            default -> token;
361	        };
362	    }
363	
364	    /**
365	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
366	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
367	     *
368	     * @param telephone the normalized (E.164) telephone of the owner being created
369	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
370	     */
371	    /**
372	     * Builds the customer code assigned to a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
373	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN} is a
374	     * global 4-digit zero-padded sequence equal to one more than the current number of owners (e.g.
375	     * {@code 'SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes it.
376	     *
377	     * @param lastName the owner's last name
378	     * @return the assigned customer code
379	     */
380	    private String generateCustomerCode(String lastName) {
381	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
382	        int sequence = this.clinicService.findAllOwners().size() + 1;
383	        return String.format("%s-%04d", last3, sequence);
384	    }
385	
386	    private void rejectDuplicateTelephone(String telephone) {
387	        boolean taken = this.clinicService.findAllOwners().stream()
388	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
389	        if (taken) {
390	            throw new DuplicateTelephoneException(telephone);
391	        }
392	    }
393	
394	    /**
395	     * Rejects a create request whose owner shares both last name and address with an existing owner.
396	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
397	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
398	     * differing case) still count as the same household.
399	     *
400	     * @param lastName the last name of the owner being created
401	     * @param address the address of the owner being created
402	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
403	     */
404	    private void rejectDuplicateHousehold(String lastName, String address) {
405	        String normalizedLastName = normalizeForComparison(lastName);
406	        String normalizedAddress = normalizeForComparison(address);
407	        boolean taken = this.clinicService.findAllOwners().stream()
408	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
409	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
410	        if (taken) {
411	            throw new DuplicateHouseholdException(lastName, address);
412	        }
413	    }
414	
415	    /**
416	     * Assigns the owner being created into a shared household. When at least one existing owner has the
417	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
418	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
419	     * reused when present; otherwise a deterministic id derived from the household's last name and address
420	     * is minted, so independently created members of the same household converge on one value. When no
421	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
422	     *
423	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
424	     */
425	    private void assignHousehold(Owner owner) {
426	        String normalizedLastName = normalizeForComparison(owner.getLastName());
427	        String normalizedAddress = normalizeForComparison(owner.getAddress());
428	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
429	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
430	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
431	            .toList();
432	        if (housemates.isEmpty()) {
433	            return;
434	        }
435	        String householdId = housemates.stream()
436	            .map(Owner::getHouseholdId)
437	            .filter(id -> id != null && !id.isBlank())
438	            .findFirst()
439	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
440	        owner.setHouseholdId(householdId);
441	        for (Owner housemate : housemates) {
442	            if (!householdId.equals(housemate.getHouseholdId())) {
443	                housemate.setHouseholdId(householdId);
444	                this.clinicService.saveOwner(housemate);
445	            }
446	        }
447	    }
448	
449	    /**
450	     * Derives a stable household identifier from the normalized last name and address of a household, as
451	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
452	     * deterministic, so any owner independently joining the same household computes the same identifier.
453	     *
454	     * @param normalizedLastName the household's last name, already normalized for comparison
455	     * @param normalizedAddress the household's address, already normalized for comparison
456	     * @return a stable, shareable household identifier
457	     */
458	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
459	        String key = normalizedLastName + "|" + normalizedAddress;
460	        try {
461	            byte[] digest = MessageDigest.getInstance("SHA-256")
462	                .digest(key.getBytes(StandardCharsets.UTF_8));
463	            StringBuilder sb = new StringBuilder(digest.length * 2);
464	            for (byte b : digest) {
465	                sb.append(String.format("%02x", b));
466	            }
467	            return sb.substring(0, 16);
468	        } catch (NoSuchAlgorithmException e) {
469	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
470	        }
471	    }
472	
473	    /**
474	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
475	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
476	     * lower-cased.
477	     *
478	     * @param value the raw value to normalize (may be {@code null})
479	     * @return the normalized value, or an empty string when {@code value} is {@code null}
480	     */
481	    private String normalizeForComparison(String value) {
482	        if (value == null) {
483	            return "";
484	        }
